// Code generated by an offline NEON encoder; do not edit by hand.
// Every WORD below is the little-endian encoding of the mnemonic in its
// trailing comment, assembled and verified with the system assembler. The
// kernels are bit-exact with AddResidualPlaneBlock's scalar inner loop
// (see plane.go): widen prediction and residual to s32 lanes, add, clamp to
// [0, max] with smax(0)/smin(max), then narrow back. The s32 intermediate
// matches the reference, which performs the add and clamp in Go int and so
// never overflows.
//
// The main kernels process the leading width&^7 columns of every row in groups
// of eight lanes; the Go wrapper handles the width&7 tail and all validation.
// Separate 4-wide kernels cover the common narrow transform block without
// reading beyond the four valid samples in a tightly-strided row.
//
// Registers v0..v7 only are used (no v8..v15 callee-saved clobber).

//go:build arm64 && !purego

#include "textflag.h"

// func addResidual8NEONAsm(dst *byte, dstStride uintptr, res *int16, resStride uintptr, max uint32, groups uintptr, height uintptr)
//
// 8-bit destination: each sample is one byte. groups is the number of 8-lane
// vector groups per row (width>>3). dstStride/resStride are in bytes; res
// advances by 16 bytes (8 int16) per group, dst by 8 bytes per group.
TEXT ·addResidual8NEONAsm(SB), NOSPLIT, $0-56
	MOVD dst+0(FP), R0
	MOVD dstStride+8(FP), R1
	MOVD res+16(FP), R2
	MOVD resStride+24(FP), R3
	MOVW max+32(FP), R12
	MOVD groups+40(FP), R4
	MOVD height+48(FP), R5

	WORD $0x4f000406 // movi v6.4s, #0
	WORD $0x4e040d87 // dup v7.4s, w12

rowLoop8:
	CBZ  R5, done8
	MOVD R0, R6 // dst row cursor (predicted pixels, in place)
	MOVD R2, R7 // res row cursor
	MOVD R4, R8 // groups remaining

colLoop8:
	CBZ  R8, rowAdvance8
	WORD $0x0c4070c0 // ld1 {v0.8b}, [x6]
	WORD $0x4c4074e1 // ld1 {v1.8h}, [x7]
	WORD $0x2f08a400 // uxtl v0.8h, v0.8b
	WORD $0x0f10a422 // sxtl v2.4s, v1.4h
	WORD $0x4f10a423 // sxtl2 v3.4s, v1.8h
	WORD $0x2f10a404 // uxtl v4.4s, v0.4h
	WORD $0x6f10a405 // uxtl2 v5.4s, v0.8h
	WORD $0x4ea28484 // add v4.4s, v4.4s, v2.4s
	WORD $0x4ea384a5 // add v5.4s, v5.4s, v3.4s
	WORD $0x4ea66484 // smax v4.4s, v4.4s, v6.4s
	WORD $0x4ea664a5 // smax v5.4s, v5.4s, v6.4s
	WORD $0x4ea76c84 // smin v4.4s, v4.4s, v7.4s
	WORD $0x4ea76ca5 // smin v5.4s, v5.4s, v7.4s
	WORD $0x0e612884 // xtn v4.4h, v4.4s
	WORD $0x4e6128a4 // xtn2 v4.8h, v5.4s
	WORD $0x0e212884 // xtn v4.8b, v4.8h
	WORD $0x0c0070c4 // st1 {v4.8b}, [x6]
	ADD  $8, R6, R6
	ADD  $16, R7, R7
	SUB  $1, R8, R8
	B    colLoop8

rowAdvance8:
	ADD  R1, R0, R0
	ADD  R3, R2, R2
	SUB  $1, R5, R5
	B    rowLoop8

done8:
	RET

// func addResidual8x4NEONAsm(dst *byte, dstStride uintptr, res *int16, resStride uintptr, max uint32, height uintptr)
//
// 8-bit destination, exactly four samples per row. Each row loads/stores four
// bytes but still performs the add/clamp/narrow in four s32 NEON lanes.
TEXT ·addResidual8x4NEONAsm(SB), NOSPLIT, $0-48
	MOVD dst+0(FP), R0
	MOVD dstStride+8(FP), R1
	MOVD res+16(FP), R2
	MOVD resStride+24(FP), R3
	MOVW max+32(FP), R12
	MOVD height+40(FP), R5

	WORD $0x4f000406 // movi v6.4s, #0
	WORD $0x4e040d87 // dup v7.4s, w12

rowLoop8x4:
	CBZ  R5, done8x4
	MOVWU (R0), R6
	VMOV R6, V0.S[0]
	VLD1 (R2), [V1.H4]
	WORD $0x2f08a400 // uxtl v0.8h, v0.8b
	WORD $0x0f10a422 // sxtl v2.4s, v1.4h
	WORD $0x2f10a404 // uxtl v4.4s, v0.4h
	WORD $0x4ea28484 // add v4.4s, v4.4s, v2.4s
	WORD $0x4ea66484 // smax v4.4s, v4.4s, v6.4s
	WORD $0x4ea76c84 // smin v4.4s, v4.4s, v7.4s
	WORD $0x0e612884 // xtn v4.4h, v4.4s
	WORD $0x0e212884 // xtn v4.8b, v4.8h
	VMOV V4.S[0], R6
	MOVW R6, (R0)
	ADD  R1, R0, R0
	ADD  R3, R2, R2
	SUB  $1, R5, R5
	B    rowLoop8x4

done8x4:
	RET

