	WORD $0x4ea76c42 // smin v2.4s, v2.4s, v7.4s
	WORD $0x4ea76c63 // smin v3.4s, v3.4s, v7.4s
	WORD $0x0e612842 // xtn v2.4h, v2.4s
	WORD $0x4e612862 // xtn2 v2.8h, v3.4s
	WORD $0x4c0074c2 // st1 {v2.8h}, [x6]
	ADD  $16, R6, R6
	ADD  $16, R7, R7
