	WORD $0x4f000406 // movi v6.4s, #0
	WORD $0x4e040d87 // dup v7.4s, w12

rawRowLoop8:
	CBZ  R5, rawDone8
	MOVD R0, R6 // dst row cursor
	MOVD R2, R7 // raw row cursor
	MOVD R4, R8 // groups remaining

